const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(' ').map(Number);
const [n, k, l, c, d, p, nl, np] = input;

const totalDrink = k * l;
const totalSlices = c * d;
const totalSalt = p;

const toastsByDrink = Math.floor(totalDrink / nl);
const toastsByLime = totalSlices;
const toastsBySalt = Math.floor(totalSalt / np);

const maxToastsTotal = Math.min(toastsByDrink, toastsByLime, toastsBySalt);
const result = Math.floor(maxToastsTotal / n);

console.log(result);

